new=''' async function saveDaily(){if(!supabase||!session||!dp||!dl||!ds)return msg("Select monthly plan, line and shift");let planned=Math.max(0,Math.floor(+planQuantity||0)),hourly=hours.reduce((n,h)=>n+(+h.planned_quantity||0),0),productive=Math.max(0,dur(start,end)-((+breakMinutes||0)/60)),cap=Math.floor(productive*(+rate||0)),p=plans.find(x=>x.id===dp),remaining=(p?.imported_serial_quantity||0)-(alloc[dp]||0);if(!planned)return msg("Enter planned quantity");if(hourly>cap)return msg(`Hourly target ${hourly} exceeds shift capacity ${cap}`);if(hourly>planned)return msg(`Hourly target ${hourly} cannot exceed planned quantity ${planned}`);if(planned>remaining)return msg(`Only ${remaining.toLocaleString()} serials remain`);let all=await supabase.from("serial_registry").select("id").eq("monthly_plan_id",dp).limit(100000),used=await supabase.from("daily_plan_serials").select("serial_registry_id,daily_production_plans!inner(monthly_plan_id)").eq("daily_production_plans.monthly_plan_id",dp).in("allocation_status",["allocated","produced"]);if(all.error||used.error)return msg(all.error?.message||used.error?.message||"");let set=new Set((used.data||[]).map((x:any)=>x.serial_registry_id)),ids=(all.data||[]).filter(x=>!set.has(x.id)).slice(0,planned);if(ids.length<planned)return msg(`Only ${ids.length} serials are available`);let{data:d,error}=await supabase.from("daily_production_plans").insert({monthly_plan_id:dp,production_date:date,line_id:dl,shift_id:ds,shift_start:`${start}:00`,shift_end:`${end}:00`,break_minutes:+breakMinutes||0,planned_quantity:planned,target_per_hour:+rate,planned_hours:productive,max_capacity_quantity:cap,status:"planned",created_by:session.user.id}).select("id").single();if(error||!d)return msg(error?.message||"Daily plan failed");let m=await supabase.from("daily_plan_manpower").upsert({daily_plan_id:d.id,manpower_category:"production",manpower_count:+manpower||0,actual_count:+actualManpower||0},{onConflict:"daily_plan_id,manpower_category"});if(m.error)return msg(m.error.message);for(let i=0;i<ids.length;i+=500){let r=await supabase.from("daily_plan_serials").insert(ids.slice(i,i+500).map(x=>({daily_plan_id:d.id,serial_registry_id:x.id,created_by:session.user.id})));if(r.error)return msg(r.error.message)}await saveHours(d.id);setModal(null);await loadAll();msg("",`Daily plan created: ${planned.toLocaleString()} planned · ${cap.toLocaleString()} max capacity.`)}
'''
